// Filter & Select Topic — JAC-1763 K-Food 워크플로
// 입력: items[0].json.items (네이버 뉴스 응답)
// 출력: 선정된 1건 + 메타데이터

const BLACKLIST_DOMAINS = [
  'news.naver.com/sports',
  'dcinside.com',
  'theqoo.net',
  'pann.nate.com',
  'instiz.net',
];
const BLACKLIST_KEYWORDS = [
  '음주운전', '마약', '폭행', '사망', '장례',
  '19금', '노출', '이재명', '윤석열', '한동훈', '조국',
  '사기', '절도', '살인', '성적', '선정적', '음란',
  '식중독', '위생사고', '위생 사고', '집단발병', '집단 발병',
  '리콜', '회수', '오염', '비위생',
];

function stripHtml(s) {
  return (s || '').replace(/<[^>]+>/g, '').replace(/&[^;]+;/g, ' ').trim();
}

function isBlocked(item) {
  const title = stripHtml(item.title);
  const desc = stripHtml(item.description);
  const url = item.originallink || item.link || '';
  const text = (title + ' ' + desc).toLowerCase();
  if (BLACKLIST_KEYWORDS.some(k => text.includes(k))) return true;
  if (BLACKLIST_DOMAINS.some(d => url.includes(d))) return true;
  return false;
}

const input = $input.first().json;
const items = input.items || [];
const body = $('Webhook Trigger').first().json.body || {};
const keyword = body.keyword || '';

const filtered = items.filter(i => !isBlocked(i));
if (filtered.length === 0) {
  return [{ json: {
    error: 'no_candidates',
    reason: '네이버 검색 결과가 모두 필터링됨 (식중독/위생 사고 등 K-푸드 추가 차단어 포함)',
    keyword,
    total_received: items.length,
  } }];
}

const topItem = filtered[0];
const title = stripHtml(topItem.title);
const description = stripHtml(topItem.description);

// 키워드의 첫 단어를 음식 제목 후보로
const dish_guess = keyword.split(' ')[0] || '';

return [{
  json: {
    keyword,
    selected: {
      title,
      description,
      source_url: topItem.originallink || topItem.link,
      pub_date: topItem.pubDate,
      dish_guess,
    },
    total_received: items.length,
    candidates_after_filter: filtered.length,
  },
}];

