// Format Output + Self-Check (12항목) + no-ai-copy 검증 — JAC-1763
// 입력: Claude 응답
// 출력: 검증 결과 + 정제된 컨텐츠 (category=k-food, ko/en 이중 언어)

const BLOCKED_KEYWORDS = ['음주운전','마약','폭행','사망','장례','19금','노출','이재명','윤석열','한동훈','조국','사기','절도','살인','성적','선정적','음란','식중독','위생사고','집단발병','리콜','회수','오염','비위생'];

// JAC-1713 npm run check:no-ai-copy 패턴과 동일
const NO_AI_COPY_PATTERN = /(AI[- ](generated|curated|powered)|AI가\s?정리|자동\s?생성\s?콘텐츠|Generated:)/i;

const raw = $input.first().json;
const contentText = raw?.content?.[0]?.text || '';

let parsed = null;
let parseError = null;
try {
  parsed = JSON.parse(contentText);
} catch (e) {
  const m = contentText.match(/\{[\s\S]*\}/);
  if (m) {
    try { parsed = JSON.parse(m[0]); } catch (e2) { parseError = e2.message; }
  } else {
    parseError = e.message;
  }
}

if (!parsed) {
  return [{ json: {
    ok: false,
    reason: 'claude_response_parse_failed',
    parseError,
    raw_excerpt: contentText.substring(0, 500),
  } }];
}

const ko = parsed.ko || {};
const en = parsed.en || {};
const koSec = ko.sections || {};
const enSec = en.sections || {};

const koBodyText = [
  koSec.intro,
  koSec.what_it_is,
  koSec.cultural_context,
  koSec.how_to_enjoy,
  koSec.closing,
].filter(Boolean).join(' ');

const enBodyText = [
  enSec.intro,
  enSec.what_it_is,
  enSec.cultural_context,
  enSec.how_to_enjoy,
  enSec.closing,
].filter(Boolean).join(' ');

const allText = [
  ko.title, ko.slug, ko.meta_description, koBodyText,
  en.title, en.slug, en.meta_description, enBodyText,
  (parsed.tags || []).join(' '),
].filter(Boolean).join(' ');

const korean_chars = (koBodyText.match(/[\uAC00-\uD7AF]/g) || []).length;
const en_word_count = enBodyText.trim() ? enBodyText.trim().split(/\s+/).length : 0;
const blocked_kw = BLOCKED_KEYWORDS.find(k => allText.includes(k));
const ai_copy_match = allText.match(NO_AI_COPY_PATTERN);

const checks = {
  '01_category_is_k_food': parsed.category === 'k-food',
  '02_ko_korean_chars_min_600': korean_chars >= 600,
  '03_en_word_count_min_200': en_word_count >= 200,
  '04_ko_title_exists_under_60': !!(ko.title && ko.title.length > 0 && ko.title.length <= 60),
  '05_en_title_exists_under_70': !!(en.title && en.title.length > 0 && en.title.length <= 70),
  '06_ko_slug_exists': !!(ko.slug && ko.slug.length > 0),
  '07_en_slug_exists': !!(en.slug && en.slug.length > 0),
  '08_ko_meta_description_under_160': !!(ko.meta_description && ko.meta_description.length > 0 && ko.meta_description.length <= 160),
  '09_en_meta_description_under_160': !!(en.meta_description && en.meta_description.length > 0 && en.meta_description.length <= 160),
  '10_tags_exist_and_are_array': !!(parsed.tags && Array.isArray(parsed.tags) && parsed.tags.length > 0),
  '11_no_blocked_keywords': !blocked_kw,
  '12_no_ai_copy_pattern': !ai_copy_match,
};
// >>> JAC-1895 hexagon-anchor-backlink BEGIN
// Hexagon mode is opt-in via `body.hexagon_id`. When absent, we auto-pass to
// preserve the legacy single-article daily routine. Sister domains in hexagon
// mode must include the canonical `/dramas/<hexagon_id>` backlink at least
// once in the collected body+meta text. The k-drama anchor self-passes.
const hxTrigger = $('Webhook Trigger').first().json.body || {};
const hxId = hxTrigger.hexagon_id || null;
const hxCategory = "k-food";
let hxBacklinkOk;
if (!hxId) {
  hxBacklinkOk = true; // legacy mode
} else {
  hxBacklinkOk = (allText || '').includes('/dramas/' + hxId);
}
checks['14_anchor_backlink_present'] = hxBacklinkOk;
// <<< JAC-1895 hexagon-anchor-backlink END
const pass = Object.values(checks).every(Boolean);
const failures = Object.entries(checks).filter(([k,v])=>!v).map(([k])=>k);

return [{
  json: {
    ok: pass,
    self_check: checks,
    self_check_failures: failures,
    self_check_summary: pass ? `${Object.keys(checks).length}/${Object.keys(checks).length} 통과` : `${Object.values(checks).filter(Boolean).length}/${Object.keys(checks).length} 통과 — 미통과: ${failures.join(', ')}`,
    blocked_keyword_hit: blocked_kw || null,
    ai_copy_hit: ai_copy_match ? ai_copy_match[0] : null,
    korean_chars,
    en_word_count,
    draft: parsed,
    metadata: {
      keyword: $('Filter & Select Topic').first().json.keyword,
      source: $('Filter & Select Topic').first().json.selected,
      generated_at: new Date().toISOString(),
      model: $('Webhook Trigger').first().json.body.model || 'claude-sonnet-4-6',
    },
  },
}];
